    filtered_rows = [row for row in rows if row['day'] <= 18]

    # Calculate total completed visits for each department
    department_completed = {}
    for row in filtered_rows:
        department = row['department']
        if row['outcome'] == 'completed':
            if department in department_completed:
                department_completed[department] += 1
            else:
                department_completed[department] = 1

    # If no departments, return None
    if not department_completed:
        return None

    # Calculate percentage for each department
    department_percentages = {}
    for department, count in department_completed.items():
        total_rows = len(filtered_rows)
        percentage = round(100 * count / total_rows, 1)
        department_percentages[department] = percentage

    # Filter percentages >= 30
    filtered_percentages = [ (val, key) for key, val in department_percentages.items() if val >= 30 ]

    # Sort by percentage (descending), then by department (alphabetically)
    sorted_percentages = sorted(filtered_percentages, key=lambda x: (-x[1], x[0]))

    # Prepare result
    result = []
    for val, key in sorted_percentages:
        result.append((key, val))

    # Return the list of [value, percentage] pairs
    return result
