def solve(rows):
    # Filter rows where weight_kg is less than 153, site is 'busan' or 'daegu', and phase is 'shipped'
    filtered_rows = [row for row in rows if row["weight_kg"] < 153 and row["site"] in {"busan", "daegu"} and row["phase"] == "shipped"]

    # Extract days and sort them
    days = sorted(set(row["day"] for row in filtered_rows))

    if not days:
        return [0, None]

    # Find the longest consecutive block of days
    max_length = 1
    current_length = 1
    start_day = days[0]

    for i in range(1, len(days)):
        if days[i] == days[i - 1] + 1:
            current_length += 1
            if current_length > max_length:
                max_length = current_length
                start_day = days[i - 1]
        else:
            current_length = 1

    if max_length == 1:
        return [0, None]
    else:
        return [max_length, start_day]
```

