def solve(rows):
    # Filter rows where fee is less than 164
    filtered_rows = [row for row in rows if row['fee'] < 164]

    if not filtered_rows:
        return None

    # Group rows by department and calculate the sum of duration_min * fee
    department_sums = {}
    for row in filtered_rows:
        department = row['department']
        duration_min = row['duration_min']
        fee = row['fee']
        key = (department, department)  # Use department as the tiebreaker
        department_sums[key] = department_sums.get(key, 0) + duration_min * fee

    # Find the department with the highest sum
    max_sum = -1
    best_department = None
    for (dept, _), total in department_sums.items():
        if total > max_sum:
            max_sum = total
            best_department = dept
        elif total == max_sum:
            if dept < best_department:
                best_department = dept

    return best_department
