        packages = row['packages']
        if driver not in driver_packages:
            driver_packages[driver] = []
        driver_packages[driver].append(packages)

    # Calculate median for each driver
    result = {}
    for driver, packages in driver_packages.items():
        sorted_packages = sorted(packages)
        n = len(sorted_packages)
        mid = n // 2
        if n % 2 == 1:
            median = sorted_packages[mid]
        else:
            median = (sorted_packages[mid - 1] + sorted_packages[mid]) / 2
        result[driver] = round(median, 1)

    return result
