def solve(rows):
    from statistics import median
    from collections import defaultdict

    driver_packages = defaultdict(list)
    for row in rows:
        driver = row['driver']
        packages = row['packages']
        driver_packages[driver].append(packages)

    result = {}
    for driver, packages in driver_packages.items():
        count = len(packages)
        if count % 2 == 1:
            median_packages = median(packages)
        else:
            median_packages = (median(packages) + median(packages)) / 2
        result[driver] = round(median_packages, 1)

    return len(result)
